module find_black_square (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [63:0] grid_packed,\n    output reg [3:0] row_center,\n    output reg [3:0] col_center,\n    output reg done\n);\n\n    // Parameters\n    localparam [5:0] N = 6'd8;\n    localparam [5:0] M = 6'd8;\n    localparam [5:0] TOTAL = 6'd64;\n\n    // States\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] SCANNING = 2'd1;\n    localparam [1:0] DONE_STATE = 2'd2;\n\n    // Registers\n    reg [1:0] state;\n    reg [5:0] idx;\n    reg [2:0] min_row;\n    reg [2:0] max_row;\n    reg [2:0] min_col;\n    reg [2:0] max_col;\n\n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            idx <= 6'd0;\n            min_row <= 3'd7;\n            max_row <= 3'd0;\n            min_col <= 3'd7;\n            max_col <= 3'd0;\n            row_center <= 4'd0;\n            col_center <= 4'd0;\n            done <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= SCANNING;\n                        idx <= 6'd0;\n                        min_row <= 3'd7;\n                        max_row <= 3'd0;\n                        min_col <= 3'd7;\n                        max_col <= 3'd0;\n                    end\n                end\n\n                SCANNING: begin\n                    if (idx < TOTAL) begin\n                        reg [2:0] row = idx[5:3];\n                        reg [2:0] col = idx[2:0];\n                        reg cell = grid_packed[idx];\n\n                        if (cell) begin\n                            if (row < min_row) min_row <= row;\n                            if (row > max_row) max_row <= row;\n                            if (col < min_col) min_col <= col;\n                            if (col > max_col) max_col <= col;\n                        end\n\n                        idx <= idx + 6'd1;\n                    end\n\n                    if (idx == TOTAL - 1) begin\n                        state <= DONE_STATE;\n                    end\n                end\n\n                DONE_STATE: begin\n                    row_center <= (min_row + max_row) / 2 + 4'd1;\n                    col_center <= (min_col + max_col) / 2 + 4'd1;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule